import json,pathlib,html,shutil,os,re,math,datetime
ROOT=pathlib.Path(__file__).resolve().parents[1]
CATS={'fuel':'Petroleum & energy','produce':'Fruit & vegetables','meat':'Meat & poultry','grocery':'Groceries','metals':'Gold & silver','currency':'Currencies','construction':'Building materials','electronics':'Electronics','household':'Household','apparel':'Clothing & footwear','services':'Labour & services','agriculture':'Agriculture'}
def validate(rows):
 ids=set()
 for r in rows:
  assert re.fullmatch(r'[a-z0-9-]+',r['id']),'Invalid item ID'
  assert r['id'] not in ids,'Duplicate item ID';ids.add(r['id'])
  assert r['category'] in CATS
  assert isinstance(r['price'],(int,float)) and not isinstance(r['price'],bool) and math.isfinite(r['price']) and 0<r['price']<1e10
  assert r['source'].startswith('https://')
  datetime.date.fromisoformat(r['date'])
  assert all(isinstance(r.get(k),str) and r[k].strip() for k in ['name','unit','city','kind'])
 return rows
def build():
 rows=validate(json.loads((ROOT/'data/prices.json').read_text()));sheets=json.loads((ROOT/'data/sheets.json').read_text());hist=json.loads((ROOT/'data/history.json').read_text());out=ROOT/'dist'
 shutil.rmtree(out,ignore_errors=True);out.mkdir()
 for f in ['style.css','app.js','editor.html','editor.js']:shutil.copy(ROOT/f,out/f)
 shutil.copytree(ROOT/'data',out/'data');shutil.copytree(ROOT/'assets',out/'assets')
 # Original PBS files can be opened from within the source library.
 for k in ['construction','weekly','monthly']:
  p=ROOT/'raw'/f'{k}.xlsx'
  if p.exists():shutil.copy(p,out/'assets'/f'pbs-{k}.xlsx')
 for r in rows:
  a=hist.setdefault(r['id'],[])
  if not any(p['date']==r['date'] and p['price']==r['price'] for p in a):
   a[:]=[p for p in a if p['date']!=r['date']];a.append({'date':r['date'],'price':r['price'],'source':r['source']});a.sort(key=lambda p:p['date'])
 (out/'data/history.json').write_text(json.dumps(hist,ensure_ascii=False,separators=(',',':')))
 E=lambda x:html.escape(str(x),quote=True)
 base=os.environ.get('SITE_URL','https://smtalhadv-web.github.io/pakistan-price-watch').rstrip('/')
 def page(title,body,path='index.html',prefix=''):
  desc=f'{title}. Source-linked Pakistan price quotes, units, locations and effective dates. Official notifications and surveyed market averages are labelled separately.'
  return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#102b27"><title>{E(title)} | Pakistan Price Watch</title><meta name="description" content="{E(desc)}"><link rel="canonical" href="{E(base+'/'+path)}"><meta property="og:title" content="{E(title)}"><meta property="og:description" content="{E(desc)}"><link rel="stylesheet" href="{prefix}style.css"></head><body><a class="skip" href="#main">Skip to content</a><header><a class="brand" href="{prefix}index.html"><span class="brandmark">P<span>↗</span></span><span>PRICE<strong>WATCH</strong><small>PAKISTAN MARKET MONITOR</small></span></a><nav><a href="{prefix}index.html">Markets</a><a href="{prefix}index.html#sheets">Official rate sheets</a><a href="{prefix}methodology.html">Sources</a><a class="navbutton" href="{prefix}editor.html">Update desk ↗</a></nav></header>{body}<footer><span>◈ Pakistan Price Watch · Independent, source-linked price reference</span><a href="{prefix}methodology.html">Methodology & privacy</a><span>No fabricated trends. Source dates always preserved.</span></footer><script src="{prefix}app.js" defer></script></body></html>'''
 def table(items,prefix='',interactive=False):
  h='<div class="tablewrap"><table class="quotes"><thead><tr><th>Item / market</th><th>Location</th><th>Price · PKR</th><th>Unit</th><th>Source date</th><th>Basis</th><th>History</th><th>Source</th></tr></thead><tbody id="quote-body">'
  for r in items:
   h+=f'''<tr data-id="{E(r['id'])}"><td><a class="itemlink" href="{prefix}items/{E(r['id'])}.html">{E(r['name'])}</a><small>{E(CATS[r['category']])}</small></td><td>{E(r['city'])}</td><td class="number">{r['price']:,.2f}</td><td>{E(r['unit'])}</td><td><time>{E(r['date'])}</time></td><td><span class="tag">{E(r['kind'])}</span></td><td>{'View chart' if len(hist.get(r['id'],[]))>1 else 'Single quote'}</td><td><a href="{E(r['source'])}" target="_blank" rel="noopener noreferrer">Source ↗</a></td></tr>'''
  return h+'</tbody></table></div>'
 cities=sorted({r['city']for r in rows});opts=lambda values:''.join(f'<option value="{E(k)}">{E(v)}</option>'for k,v in values)
 report=json.loads((ROOT/'data/update-report.json').read_text());counts={k:sum(r['category']==k for r in rows)for k in CATS}
 body=f'''<div class="marketbar"><span class="marketdot"></span> SOURCED DATA · NOT A LIVE EXCHANGE <span class="markettime">Last collection: {E(report['checked_at'][:16].replace('T',' '))} UTC</span></div><div class="workspace"><aside class="sidebar"><div class="side-label">MARKETS</div><button class="sidecat active" data-cat="">◫ <span>All prices</span><b>{len(rows)}</b></button>'''+''.join(f'<button class="sidecat" data-cat="{k}"><span>{E(v)}</span><b>{counts[k]}</b></button>'for k,v in CATS.items())+'''<div class="side-label spaced">DATA LIBRARY</div><a href="#sheets">▧ Official image sheets</a><a href="data/prices.json">↓ Download JSON</a><a href="data/update-report.json">◷ Update report</a><a href="methodology.html">ⓘ How prices are checked</a></aside><main id="main"><div class="page-title"><div><div class="eyebrow">THE EVERYDAY ECONOMY, IN ONE VIEW</div><h1>Pakistan market overview<span>.</span></h1><p>Compare published prices. Follow real changes. Check the original source.</p></div><span class="edition">PKR <span>₨</span></span></div>'''
 body+=f'''<div class="stats"><div><span>PRICE RECORDS</span><strong>{len(rows):,}</strong><small>City, unit and quote basis preserved</small></div><div><span>LOCATIONS</span><strong>{len(cities)}</strong><small>National rates + surveyed cities</small></div><div><span>MARKET CATEGORIES</span><strong>{len(CATS)}</strong><small>Food, fuel, metals and more</small></div><div><span>OFFICIAL IMAGE SHEETS</span><strong>{sum((ROOT/r['file']).exists() for r in sheets)}</strong><small>Read and zoom inside the site</small></div></div>'''
 body+='''<div class="chart-row"><section class="panel chartpanel"><div class="panelhead"><div><div class="eyebrow">PRICE HISTORY</div><h2 id="chart-name">Gold · 24K</h2><div id="chart-meta" class="muted">Loading source-linked observations…</div></div><label class="visually-hidden" for="chart-select">Select chart item</label><select id="chart-select">'''+opts((r['id'],r['name']+' · '+r['city']+' / '+r['unit'])for r in rows if len(hist.get(r['id'],[]))>1)+'''</select></div><div class="chartquote"><strong id="chart-value">—</strong><span id="chart-change"></span><div class="ranges" role="group" aria-label="Chart time range"><button data-range="7">7D</button><button class="active" data-range="30">1M</button><button data-range="90">3M</button><button data-range="all">All</button></div></div><div id="chart" aria-live="polite"></div><p id="chart-caption" class="chartcaption"></p></section><section class="panel watchpanel"><div class="panelhead"><div><div class="eyebrow">AT A GLANCE</div><h2>Market watch</h2></div><span class="tag">Latest quotes</span></div><div id="watchlist"></div><p class="chartcaption">Changes compare the last two recorded source dates, which may not be consecutive days.</p></section></div>'''
 body+='''<section class="panel listpanel" id="prices"><div class="panelhead"><div><div class="eyebrow">SOURCE-LINKED PRICE DIRECTORY</div><h2>The market list</h2></div><a href="data/prices.json" download>Export data ↓</a></div><div class="filters"><label class="searchlabel"><span class="visually-hidden">Search items</span><input id="search" type="search" placeholder="Search prices in English or Urdu…"></label><label><span class="visually-hidden">Location</span><select id="city"><option value="">All locations</option>'''+opts((c,c)for c in cities)+'''</select></label><label><span class="visually-hidden">Category</span><select id="category"><option value="">All categories</option>'''+opts(CATS.items())+'''</select></label><label><span class="visually-hidden">Quote basis</span><select id="basis"><option value="">All quote types</option><option value="official">Official notified</option><option value="weekly">Weekly survey</option><option value="monthly">Monthly survey</option><option value="retailer">Retailer listings</option><option value="reported">Reported markets</option></select></label><label><span class="visually-hidden">Sort by</span><select id="sort"><option value="recent">Newest source date</option><option value="name">Name A–Z</option><option value="low">Price low–high (check units)</option><option value="high">Price high–low (check units)</option></select></label></div><div class="listnote"><span id="count">'''+str(len(rows))+''' dated quotes</span><span>Official limits ≠ surveyed averages ≠ retailer offers</span></div>'''+table(sorted(rows,key=lambda r:r['date'],reverse=True)[:50],interactive=True)+'''<p id="empty" hidden class="empty">No matching items. Try another location or category.</p><div class="pagination"><button id="previous">← Previous</button><span id="page-label"></span><button id="next">Next →</button></div></section>'''
 body+='''<section id="sheets" class="panel sheets-panel"><div class="panelhead"><div><div class="eyebrow">ORIGINAL DOCUMENTS · KARACHI</div><h2>Official rate sheet viewer</h2></div><a href="https://commissionerkarachi.gos.pk/karachi/pricelist" target="_blank" rel="noopener">Commissioner source ↗</a></div><p class="muted">Text not available? Read the original image here. Dates below are website index dates; the date printed on the document takes precedence. Archived notifications are not presented as today's market price.</p><div class="sheetgrid">'''
 for r in sheets:
  exists=(ROOT/r['file']).exists()
  body+=f'''<article class="sheetcard"><div><span class="tag">Official document</span><h3>{E(r['title'])}</h3><p>Index date: {E(r['date'])}</p></div>'''
  if exists:body+=f'''<button class="sheet-open" data-file="{E(r['file'])}" data-title="{E(r['title'])}"><img src="{E(r['file'])}" alt="Official Karachi {E(r['title'])} rate sheet" loading="lazy"><span>View & zoom ↗</span></button>'''
  else:body+='<p class="error">Source image currently unavailable.</p>'
  body+=f'<a href="{E(r["source"])}" target="_blank" rel="noopener">Original source ↗</a></article>'
 body+='''</div><div class="downloads"><strong>PBS source workbooks</strong><a href="assets/pbs-weekly.xlsx">Weekly city prices ↗</a><a href="assets/pbs-construction.xlsx">Monthly construction ↗</a><a href="assets/pbs-monthly.xlsx">Monthly essentials ↗</a></div></section><section class="method-banner"><h2>Every price has a context.</h2><p>Always check the date, location, grade and unit. Weekly and monthly surveys are reference averages; retailers may charge differently. A single observation cannot establish a trend.</p><a href="methodology.html">Read our methodology →</a></section><noscript>JavaScript enables search and charts. Browse categories below for complete static price tables.</noscript><div class="browse-links">'''+''.join(f'<a href="categories/{k}.html">{E(v)} ({counts[k]})</a>'for k,v in CATS.items())+'''</div></main></div><dialog id="sheet-dialog"><div class="dialogbar"><strong id="sheet-title"></strong><label>Zoom <select id="zoom"><option value="100">100%</option><option value="150">150%</option><option value="200">200%</option></select></label><button id="close-sheet">Close ✕</button></div><div class="image-scroll"><img id="sheet-image" alt="Official source price sheet"></div></dialog>'''
 (out/'index.html').write_text(page('Pakistan prices, charts & official rate sheets',body))
 method='''<main id="main" class="prose panel"><div class="eyebrow">TRANSPARENT BY DESIGN</div><h1>Know what a price means.</h1><h2>Official, surveyed and listed prices</h2><p>Commissioner Karachi image sheets contain official notified rates. PBS workbooks contain weekly or monthly surveyed city averages, not price ceilings. PSO publishes dated fuel rates. PriceOye records are advertised listing prices; storage variants, warranty, stock and checkout costs must be checked with the retailer. Hamariweb currency and metals tables are secondary reported benchmarks, not direct licensed market feeds.</p><h2>Collection and date labels</h2><p>The daily GitHub workflow fetches supported public pages, price tables and official image sheets. Every quote preserves its source date or is explicitly labelled observed. Weekly dates mean week ending; monthly dates mean month end. An unsuccessful source fetch retains the last dated quote. The collection timestamp does not imply all quotes are current.</p><h2>Charts</h2><p>Charts contain source-linked historical observations only, with exact dates. Lines connect recorded observations and do not imply intraday trading or prices between observations. Change is versus the previous recorded quote. A single quote has no trend or percentage movement. Differing units and quote bases must not be compared.</p><h2>Image rates</h2><p>Original official images can be read and zoomed inside this site. Human transcriptions retain a snapshot and the original document link. The date printed on a notification takes precedence over the index date. The source's milk image currently returns 404; no milk notification price was invented. PBS surveyed milk prices remain available.</p><h2>Manual updates</h2><p>The public update desk prepares validated JSON; it cannot publish. A repository maintainer must commit the reviewed file in GitHub. No access tokens are requested or stored in the frontend.</p><h2>Privacy and independence</h2><p>No analytics, trackers or login are included. GitHub Pages may process service logs under GitHub's privacy policy. This is an independent reference, not a government website, an exchange or a guarantee of transaction prices. Sources retain their rights. Links and original source documents are provided for verification.</p></main>'''
 (out/'methodology.html').write_text(page('Sources, methodology & privacy',method,'methodology.html'))
 (out/'items').mkdir();(out/'categories').mkdir();urls=['index.html','methodology.html']
 for cat,label in CATS.items():
  items=[r for r in rows if r['category']==cat];path=f'categories/{cat}.html'
  (out/path).write_text(page(label+' prices in Pakistan',f'<main id="main" class="prose wide"><h1>{E(label)} prices</h1><p>Compare only matching units and quote types. Source dates are shown for every record.</p>'+table(items,'../')+'</main>',path,'../'));urls.append(path)
 for r in rows:
  path=f'items/{r["id"]}.html';points=hist.get(r['id'],[])
  body=f'<main id="main" class="prose panel"><div class="eyebrow">{E(CATS[r["category"]])} · {E(r["city"])}</div><h1>{E(r["name"])}</h1><p class="detail-price">Rs {r["price"]:,.2f} <small>/ {E(r["unit"])}</small></p><p>{E(r["kind"])} · Source date {E(r["date"])}</p><a href="{E(r["source"])}" target="_blank" rel="noopener">Original source ↗</a><p>{E(r.get("note","Check the original source for units, availability and transaction costs."))}</p>'
  if r.get('sheet') and (ROOT/r['sheet']).exists():body+=f'<h2>Original official rate sheet</h2><a href="../{E(r["sheet"])}"><img class="detail-sheet" loading="lazy" src="../{E(r["sheet"])}" alt="Official source notification"></a>'
  if len(points)>1:body+='<h2>Recorded price history</h2><table class="historytable"><thead><tr><th>Source date</th><th>PKR / '+E(r['unit'])+'</th></tr></thead><tbody>'+''.join(f'<tr><td>{E(p["date"])}</td><td>{p["price"]:,.2f}</td></tr>'for p in points[-30:])+'</tbody></table>'
  else:body+='<p>One observation is available. No historical trend is inferred.</p>'
  body+='</main>';(out/path).write_text(page(r['name']+' price in '+r['city'],body,path,'../'));urls.append(path)
 (out/'sitemap.xml').write_text('<?xml version="1.0"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join(f'<url><loc>{E(base+"/"+u)}</loc></url>'for u in urls)+'</urlset>')
 (out/'.nojekyll').touch();print(f'Built {len(rows)} quotes, {len(urls)} crawlable pages, {len(sheets)} sheet entries')
if __name__=='__main__':build()
